import numpy as np
import scipy.linalg as sl
import linalg2_expected as X

def close(x, ref, rtol: float = 1e-10, atol: float = 1e-12) -> bool:
    a = np.asarray(x).ravel()
    if a.shape[0] != len(ref):
        print('size', a.shape[0], len(ref))
        return False
    ok = True
    for i in range(len(ref)):
        u = a[i]
        v = ref[i]
        if abs(u - v) > atol + rtol * abs(v):
            print('mismatch', i, u, v)
            ok = False
    return ok

def closeabs(x, ref, rtol: float = 1e-10, atol: float = 1e-12) -> bool:
    # sign-insensitive (eigenvector columns)
    a = np.asarray(x).ravel()
    ok = a.shape[0] == len(ref)
    for i in range(len(ref)):
        if abs(abs(a[i]) - abs(ref[i])) > atol + rtol * abs(ref[i]):
            print('mismatch', i, a[i], ref[i])
            ok = False
    return ok

A = np.array([[4., 1., 2., .5], [1., 3., .5, .2], [2., .5, 5., 1.], [.3, .2, 1., 2.]])
G = np.array([[1., 2., 0., 1.], [-1., 1., 3., 0.], [2., 0., 1., -2.], [0., 1., 1., 1.]])
S = np.array([[4., 1., 2.], [1., 3., .5], [2., .5, 5.]])
B = np.array([[2., .3, .1, 0.], [.3, 1.5, .2, .1], [.1, .2, 1., .3], [0., .1, .3, 1.2]])
R = np.array([[1., 2., 3.], [4., 5., 6.], [7., 8., 10.], [1., 0., 1.]])

@test
def test_special_matrices():
    assert close(sl.hadamard(4).astype(float), X.had4)
    assert close(sl.leslie([0.1, 2.0, 1.0, 0.1], [0.2, 0.8, 0.7]), X.les)
    assert close(sl.companion([1, -10, 31, -30]), X.comp)
    assert close(sl.helmert(5), X.helm)
    assert close(sl.helmert(4, full=True), X.helmf)
    assert close(sl.hilbert(4), X.hilb)
    assert close(sl.invhilbert(5), X.ihilb, 1e-9)
    assert close(sl.invhilbert(5, exact=True).astype(float), X.ihilbx)
    assert close(sl.pascal(5).astype(float), X.pasc)
    assert close(sl.pascal(4, kind='lower').astype(float), X.pascl)
    assert close(sl.pascal(4, exact=False), X.pascf)
    assert close(sl.invpascal(5).astype(float), X.ipasc)
    assert close(sl.invpascal(4, kind='upper').astype(float), X.ipascu)
    assert close(sl.dft(5), X.dft4, 1e-12, 1e-14)
    assert close(sl.dft(4, scale='sqrtn'), X.dftn, 1e-12, 1e-14)
    assert close(sl.fiedler([1., 4., 12., 45., 77.]), X.fied)
    assert close(sl.fiedler_companion([1., -16., 86., -176., 105.]), X.fcomp)
    assert close(sl.convolution_matrix([1., 2., 3.], 5), X.convf)
    assert close(sl.convolution_matrix([1., 2., 3., 4.], 3, 'same'), X.convs)
    assert close(sl.convolution_matrix([1., 2., 3.], 5, 'valid'), X.convv)
    assert close(sl.khatri_rao(np.array([[1., 2., 3.], [4., 5., 6.]]),
                               np.array([[3., 4., 5.], [6., 7., 8.], [2., 3., 9.]])), X.kr)
    assert close(sl.diagsvd([1., 2.], 3, 2), X.dsvd)
test_special_matrices()

@test
def test_schur_family():
    T, Z = sl.schur(G)
    assert close(T, X.schurT)
    assert close(Z, X.schurZ)
    Tc, Zc = sl.schur(G, output='complex')
    assert close(Tc, X.schurTc)
    assert close(Zc, X.schurZc)
    Ts, Zs, sd = sl.schur(G, sort='lhp')
    assert close(Ts, X.schurTs)
    assert close(Zs, X.schurZs)
    assert sd == int(X.schursd[0])
    T2, Z2 = sl.rsf2csf(T, Z)
    assert close(T2, X.rsfT)
    assert close(Z2, X.rsfZ)
    H, Q = sl.hessenberg(G, calc_q=True)
    assert close(H, X.hessH)
    assert close(Q, X.hessQ)
    assert close(sl.hessenberg(G), X.hessH)
    Mb = np.array([[1., 100., 0.], [0.01, 1., 1e4], [1e-3, 1., 1.]])
    Bb, Tb = sl.matrix_balance(Mb)
    assert close(Bb, X.balB)
    assert close(Tb, X.balT)
    Bb2, sp = sl.matrix_balance(Mb, separate=True)
    assert close(sp[0], X.balS)
    assert close(sp[1].astype(float), X.balP)
test_schur_family()

@test
def test_qz():
    AA, BB, Q, Z = sl.qz(G, B)
    assert close(AA, X.qzAA)
    assert close(BB, X.qzBB)
    assert close(Q, X.qzQ)
    assert close(Z, X.qzZ)
    AA, BB, al, be, Q, Z = sl.ordqz(G, B, sort='lhp')
    assert close(AA, X.oqAA)
    assert close(BB, X.oqBB)
    assert close(al, X.oqal)
    assert close(be, X.oqbe)
    assert close(Q, X.oqQ)
    assert close(Z, X.oqZ)
test_qz()

@test
def test_ldl_rq_polar():
    Asym = np.array([[2., -1., 3.], [-1., 2., 0.], [3., 0., 1.]])
    lu, d, p = sl.ldl(Asym)
    assert close(lu, X.ldlL)
    assert close(d, X.ldlD)
    assert close(p.astype(float), X.ldlP)
    lu, d, p = sl.ldl(Asym, lower=False)
    assert close(lu, X.ldlLu)
    assert close(d, X.ldlDu)
    assert close(p.astype(float), X.ldlPu)
    r, q = sl.rq(R.T)
    assert close(r, X.rqR)
    assert close(q, X.rqQ)
    r, q = sl.rq(R)
    assert close(r, X.rqR2)
    assert close(q, X.rqQ2)
    r, q = sl.rq(R.T, mode='economic')
    assert close(r, X.rqRe)
    assert close(q, X.rqQe)
    u, p2 = sl.polar(R)
    assert close(u, X.polU)
    assert close(p2, X.polP)
    u, p2 = sl.polar(R, side='left')
    assert close(u, X.polUl)
    assert close(p2, X.polPl)
    rr, scl = sl.orthogonal_procrustes(R, R @ np.array([[0., 1., 0.], [-1., 0., 0.], [0., 0., 1.]]))
    assert close(rr, X.procR)
    assert close([scl], X.procS)
    assert close(sl.subspace_angles(R, np.array([[1., 0.], [0., 1.], [1., 1.], [2., 0.]])), X.sang)
    lo, up = sl.bandwidth(np.array([[1., 2., 0., 0.], [3., 1., 0., 4.], [0., 5., 1., 0.], [0., 0., 0., 1.]]))
    assert close([float(lo), float(up)], X.bw)
    assert sl.issymmetric(S) and not sl.issymmetric(G)
    assert sl.ishermitian(np.array([[1. + 0j, 2. + 1j], [2. - 1j, 3. + 0j]]))
    assert not sl.ishermitian(np.array([[1. + 0j, 2. + 1j], [2. + 1j, 3. + 0j]]))
test_ldl_rq_polar()

@test
def test_banded():
    ab = np.array([[0., 1., 2., 3., 1.], [5., 6., 7., 8., 9.], [1., 2., 3., 4., 0.]])
    bb = np.array([1., 2., 3., 4., 5.])
    assert close(sl.solve_banded((1, 1), ab, bb), X.sbtri)
    ab2 = np.array([[0., 0., 1., 2., 3.], [0., 1., 2., 3., 1.], [5., 6., 7., 8., 9.], [1., 2., 3., 4., 0.]])
    bm = np.empty((5, 2))
    for i in range(5):
        bm[i, 0] = bb[i]
        bm[i, 1] = bb[4 - i]
    assert close(sl.solve_banded((1, 2), ab2, bm), X.sbgen)
    hb = np.array([[0., 1., 1., 1., 1.], [4., 4., 4., 4., 4.]])
    assert close(sl.solveh_banded(hb, bb), X.shb)
    hb3 = np.array([[0., 0., .5, .5, .5], [0., 1., 1., 1., 1.], [6., 6., 6., 6., 6.]])
    assert close(sl.solveh_banded(hb3, bb), X.shb3)
    assert close(sl.solveh_banded(np.array([[4., 4., 4., 4., 4.], [1., 1., 1., 1., 0.]]), bb, lower=True), X.shbl)
    cb = sl.cholesky_banded(hb3)
    assert close(cb, X.cbf)
    assert close(sl.cho_solve_banded((cb, False), bb), X.cbs)
    w, v = sl.eig_banded(hb3)
    assert close(w, X.ebw)
    assert closeabs(v, X.ebv)
    assert close(sl.eig_banded(hb3, eigvals_only=True, select='i', select_range=(1, 3)), X.ebsel)
    w, v = sl.eig_banded(hb3, select='v', select_range=(5.0, 7.0))
    assert close(w, X.ebvw)
    assert closeabs(v, X.ebvv)
test_banded()

@test
def test_tridiagonal_toeplitz():
    d = np.array([3., 1., 4., 1., 5.])
    e = np.array([1., 2., -1., 0.5])
    w, v = sl.eigh_tridiagonal(d, e)
    assert close(w, X.etw)
    assert closeabs(v, X.etv)
    assert close(sl.eigvalsh_tridiagonal(d, e, lapack_driver='sterf'), X.etsterf)
    w, v = sl.eigh_tridiagonal(d, e, select='i', select_range=(1, 2))
    assert close(w, X.etiw)
    assert closeabs(v, X.etiv)
    assert close(sl.eigvalsh_tridiagonal(d, e, select='v', select_range=(0.0, 4.0)), X.etvv)
    w, v = sl.eigh_tridiagonal(d, e, lapack_driver='stev')
    assert close(w, X.etsw)
    assert closeabs(v, X.etsv)
    assert close(sl.solve_toeplitz(([1., 3., 6., 10.], [1., -1., -2., -3.]), [1., 2., 2., 5.]), X.stoep)
    assert close(sl.solve_toeplitz([4., 1., .5], np.array([[1., 2.], [3., 4.], [5., 6.]])), X.stoep2)
    assert close(sl.matmul_toeplitz(([1., 2., 3.], [1., 5., 6., 7.]), np.array([1., 2., 3., 4.])), X.mtoep)
    assert close(sl.solve_circulant([2., -1., 0., 1.], [1., 2., 3., 4.]), X.scirc)
test_tridiagonal_toeplitz()

@test
def test_solvers():
    a = np.array([[-3., -2., 0.], [-1., -1., 0.], [0., -5., -1.]])
    q = np.array([[1.], [2.], [3.]])
    assert close(sl.solve_sylvester(a, np.array([[1.]]), q), X.sylv)
    assert close(sl.solve_sylvester(G, S[:2, :2] + 2, R[:, :2].copy()), X.sylv2)
    assert close(sl.solve_continuous_lyapunov(a, np.eye(3)), X.lyap)
    assert close(sl.solve_discrete_lyapunov(0.4 * G, np.eye(4)), X.dlyap)
    assert close(sl.solve_discrete_lyapunov(0.4 * G, np.eye(4), method='bilinear'), X.dlyapb)
    ca = np.array([[4., 3.], [-4.5, -3.5]])
    cb = np.array([[1.], [-1.]])
    cq = np.array([[9., 6.], [6., 4.]])
    cr = np.array([[1.]])
    assert close(sl.solve_continuous_are(ca, cb, cq, cr), X.care, 1e-8, 1e-10)
    assert close(sl.solve_discrete_are(ca * 0.3, cb, cq + np.eye(2), cr), X.dare, 1e-8, 1e-10)
    assert close(sl.solve_continuous_are(G, R, np.eye(4), np.eye(3)), X.care2, 1e-8, 1e-10)
    assert close(sl.solve_discrete_are(0.5 * G, R, np.eye(4), np.eye(3)), X.dare2, 1e-8, 1e-10)
    E = np.eye(4) + 0.1 * np.triu(np.ones((4, 4)))
    assert close(sl.solve_continuous_are(G, R, np.eye(4), np.eye(3), e=E), X.caree, 1e-8, 1e-10)
test_solvers()
